from collections import Counter, deque

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    seen=set()
    for r in range(h):
        for c in range(w):
            color=g[r][c]
            if color==bg or (r,c) in seen:
                continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if r1-r0<2 or c1-c0<2:
                continue
            boundary={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if any(g[y][x]!=color for y,x in boundary):
                continue
            interior=[(y,x) for y in range(r0+1,r1) for x in range(c0+1,c1)]
            if not interior or any(g[y][x]!=bg for y,x in interior):
                continue
            fill=7 if ((r1-r0-1)%2==1) else 2
            for y,x in interior:
                g[y][x]=fill
    return g
